create or replace TABLE LDL_PRODUCTION.P_LEW_CORE.T_LOCATION (
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'Unique identifier of the DWH client / slice.',
	LOC_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate Key LOCATION (eindeutig ueber alle Laender / Mandanten hinweg).',
	SRC_WERKS VARCHAR(20) COMMENT 'Techn. identifier of warehouses / stores in SAP Retail source system.',
	SRC_ORIG_STORE_NR NUMBER(38,0) COMMENT 'Techn. identifier of stores in WAWI source system.',
	SRC_ORIG_WH_NR NUMBER(38,0) COMMENT 'Techn. identifier of warehouses in WAWI source system.',
	SRC_STORE_ID NUMBER(38,0) COMMENT 'Techn. identifier of stores in WAWI DWH (surrogate key).',
	SRC_WH_ID NUMBER(38,0) COMMENT 'Techn. identifier of warehouses in WAWI DWH (surrogate key).',
	SRC_ASSOC_ID VARCHAR(100) COLLATE 'en-ci' COMMENT 'Techn. identifier of warehouses in IMS source system: IMS_ESB: associations.association.id',
	LOC_TYPE_CD VARCHAR(2) COLLATE 'en-ci' COMMENT 'Code for the discriminator values for locations (store vs. warehouse).',
	LOC_NR VARCHAR(20) COLLATE 'en-ci' COMMENT 'The number by which the store or warehouse is known to the business.',
	LOC_NAME VARCHAR(100) COLLATE 'en-ci' COMMENT 'Name of the Organization / WH / Store (w/i Retail-System).',
	WH_NAME VARCHAR(100) COLLATE 'en-ci' COMMENT 'Name of the Organization / WH (w/i Immo-Mgmt-System); association.assoc_name',
	WH_ADD1_NAME VARCHAR(100) COLLATE 'en-ci' COMMENT 'Additional name part of the Organization / WH (w/i Immo-Mgmt-System); association.assoc_name2',
	WH_TXT VARCHAR(1000) COMMENT 'Free text comment regarding Organization / WH (w/i Immo-Mgmt-System); association.comments',
	LOC_STATUS_CD VARCHAR(5) COLLATE 'en-ci' COMMENT 'A code for the status of a location (active, closed, ...).',
	COUNTRY_POL_SID NUMBER(38,0) COMMENT 'The surrogate key of the country (political) in which the Organization / WH / Store is located.',
	COUNTRY_POL_CD VARCHAR(20) COMMENT 'The code for the country (political) in which the Organization / WH / Store is located.',
	OPENING_DT DATE COMMENT 'Opening-Date (Retail perspective)',
	REAL_OPENING_DT DATE COMMENT '(deprecated) The real opening date. (only relevant for GB)',
	CLOSING_DT DATE COMMENT 'Closing-Date (Retail perspective); SAP-Retail: wrf1.schld; SAP-BW: 0rt_wrf1_attr.schld; ELWIS: t_s_loc_wrf1.close_dat',
	WH_STORE_MARK VARCHAR(20) COMMENT '(deprecated) Organization-Type - Code; SAP-Retail: t001w.vlfkz; SAP-BW: t_bw_0plant_attr.vlfkz',
	WH_STORE_LABEL VARCHAR(100) COLLATE 'en-ci' COMMENT '(deprecated) Organization-Type - Descr.: A = Store; B = Warehouse',
	STORETYPE_MARK VARCHAR(20) COMMENT '(deprecated) Store-Type - Code; SAP-Retail: t001w.storetype; SAP-BW: t_bw_0plant_attr.storetype;',
	STORETYPE_LABEL VARCHAR(100) COLLATE 'en-ci' COMMENT '(deprecated) Store-Type - Descr.: 0 = Filiale; 1 = Warenhaus; 2 = Shop',
	CUSTOMER_CD VARCHAR(20) COMMENT '(deprecated) Kundennummer des Betriebs / der Lokation; SAP-Retail: t001w.kunnr; SAP-BW: t_bw_0plant_attr.kunnr;',
	GLOBAL_LOC_CTRY_CD VARCHAR(20) COMMENT '(deprecated) Laendercode der Location; SAP-Retail: string_substring(t001w.zkebnr, 1, 2); SAP-BW: t_bw_0plant_attr.zkebnr;',
	GLOBAL_LOC_ID VARCHAR(20) COMMENT '(deprecated) Klarname - Werksnummer; SAP-Retail: t001w.zkebnr; SAP-BW: t_bw_0plant_attr.zkebnr;',
	GLOBAL_LOC_ID_LENGTH NUMBER(38,0) COMMENT '(deprecated) Laenge der Werksnummer; SAP-Retail: string_length(t001w.zkebnr); SAP-BW: t_bw_0plant_attr.zkebnr;',
	GLOBAL_LOC_TYPE_CD VARCHAR(20) COMMENT '(deprecated) ; SAP-Retail: t001w.string_substring(t001w.zkebnr,3,1); SAP-BW: t_bw_0plant_attr.zkebnr; ',
	LOC_NAME2 VARCHAR(100) COLLATE 'en-ci' COMMENT 'Alternative name of the Organization / WH / Store; SAP-Retail: ?; SAP-BW: t_bw_0plant_text.txtmd;',
	LOC_SID_SUCCESSOR_ACT NUMBER(38,0) COMMENT '(deprecated) see t_location_hist.loc_sid_successor',
	LONGITUDE NUMBER(9,6) COMMENT '(deprecated) see t_address',
	LATITUDE NUMBER(9,6) COMMENT '(deprecated) see t_address',
	SAP_CREATION_WRF1_DT DATE COMMENT '(deprecated) (?) Datum, an dem der Satz in SAP-Retail-Tabelle WRF1 hinzugefuegt wurde; SAP-Retail: wrf1.erdat;',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Identifier of the last run which inserted or updated the record. -1 means manually inserted.',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Creation timestamp of the record in the DWH.',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Timestamp of the last update of the record in the DWH.',
	constraint PK_T_LOCATION primary key (LOC_SID)
)COMMENT='$Revision: 0000 $. Stores and Warehouses (Organizational View - not the physical buildings).\n             Warehouses may represent Sales Org. (VGES), Delivery Org. (BGES), Expansion Org., Owner Org., Balance Sheet Org., Country Org.'
;